    "Reciprocity": {"Explanation": "The email offers a chance to provide feedback (which can be seen as a gift) and asks for a favor in return by encouraging completion of the pulse survey."},
    "Scarcity": {"Explanation": "The email implies scarcity by mentioning that the opportunity to participate is limited to a specific timeframe (between now and Friday, October 27)."},
    "Authority": {"Explanation": "The email does not explicitly reference any authority or credible source to establish trust."},
    "Commitment/Consistency": {"Explanation": "The email references prior behavior by thanking those who have already completed the survey, which could encourage others to complete it as well."},
    "Liking": {"Explanation": "The email does not use personalization, flattery, or familiarity to build trust or rapport."},
    "Social proof": {"Explanation": "The email references social proof by mentioning that nearly 27% of all ETS employees have completed the survey, suggesting that many others have participated and find it valuable."}
}

